 function newProduct(){openModal('Nuevo producto','Registrá el producto y su stock inicial.','<form data-form="product"><div class="form-grid">'+field('Nombre','name','text','maxlength="100" placeholder="Ej.: Termo de acero"')+field('Código / SKU','sku','text','maxlength="40" placeholder="Ej.: TER-009"')+field('Categoría','category','text','maxlength="60" value="General"')+field('Precio de venta · UYU','price','number','min="0" step="0.01" value="0"')+field('Stock inicial','stock','number','min="0" step="1" value="0"')+field('Stock mínimo','min','number','min="0" step="1" value="0"')+'</div>'+formEnd('Crear producto'));}
