 function movement(id){openModal('Movimiento de stock','Ingresos y ajustes con motivo registrado.','<form data-form="movement"><div class="form-grid"><div class="form-row full"><label for="f-productId">Producto</label><select name="productId" id="f-productId">'+state.products.map(p=>'<option value="'+p.id+'" '+(p.id===id?'selected':'')+'>'+esc(p.name)+' · '+p.stock+' en depósito</option>').join('')+'</select></div><div class="form-row"><label for="f-kind">Tipo</label><select id="f-kind" name="kind"><option>Ingreso</option><option>Ajuste positivo</option><option>Ajuste negativo</option></select></div>'+field('Cantidad','qty','number','min="1" step="1" value="1"')+'<div class="form-row full"><label for="f-note">Motivo / referencia</label><textarea name="note" id="f-note" required maxlength="500" placeholder="Ej.: compra recibida, recuento físico…"></textarea><span class="form-help">Un ajuste negativo no puede consumir unidades reservadas para otros pedidos.</span></div></div>'+formEnd('Guardar movimiento'));}
