 function orderCustomerMode(useNew){
  const select=$('#f-customerId'),panel=$('#order-new-customer'),toggle=$('[data-action="order-customer-mode"]');if(!select||!panel)return;
  if(useNew&&select.value!=='__new__')select.dataset.previous=select.value;
  select.classList.toggle('hidden',useNew);select.disabled=useNew;panel.disabled=!useNew;panel.classList.toggle('hidden',!useNew);
  toggle.setAttribute('aria-expanded',String(useNew));toggle.innerHTML=useNew?'Elegir cliente registrado':icon('plus')+'Nuevo cliente';
  $('[data-form="order"] button[type="submit"]').textContent=useNew?'Guardar cliente y pedido':'Guardar y reservar';
  $('#form-error')?.classList.add('hidden');
  if(!useNew){select.value=select.dataset.previous||'';select.focus();}else $('#f-newName').focus();
 }
