 function download(filename,content,type){const blob=new Blob([content],{type}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=filename;document.body.appendChild(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),1000);}
 function exportCsv(){const safe=v=>{let t=String(v==null?'':v);if(/^[=+@-]/.test(t))t="'"+t;return '"'+t.replace(/"/g,'""')+'"';};const rows=[['Pedido','Cliente','Entrega prevista','Estado','Total UYU','Cobrado UYU','Saldo UYU','Empresa transportista','Matrícula','Conductor','Tipo de documento','Número de documento'],...state.orders.map(o=>{const t=M.transportFor(o);return [o.id,customer(o.customerId).name,o.deliveryDate,o.status,M.total(o),o.paid,M.due(o),t.company,t.vehiclePlate,t.driverName,t.documentType,t.documentNumber];})];download('Pedidos_demo.csv','\ufeff'+rows.map(r=>r.map(safe).join(';')).join('\r\n'),'text/csv;charset=utf-8');toast('Reporte de pedidos descargado.');}
